import {Component} from '@angular/core';
import {ActivatedRoute,RouterModule} from '@angular/router';
import {LanguageService} from '../services/language.service';
@Component({selector:'app-asset-unavailable',standalone:true,imports:[RouterModule],template:`<main><h1>{{management?(fr?'Espace de gestion privé':'Private management area'):lookup?(fr?'Impossible de charger l’annonce':'Could not load the listing'):fr?'Annonce indisponible au public':'Listing not publicly available'}}</h1><p [hidden]="management||lookup">{{fr?'Si vous êtes propriétaire, connectez-vous sur cette adresse pour prévisualiser votre annonce. La connexion sur godirect.fr ou localhost ne vous connecte pas automatiquement sur ce sous-domaine.':'If you own this listing, sign in on this address to preview it. Signing in on godirect.fr or localhost does not automatically sign you in on this subdomain.'}}</p><a routerLink="/account/login" [queryParams]="{returnUrl:'/'}">{{fr?'Se connecter':'Sign in'}}</a> <a routerLink="/">{{management?(fr?'Voir l’annonce publique':'View public listing'):fr?'Réessayer':'Try again'}}</a><p [hidden]="management||lookup">{{fr?'Pour les visiteurs, l’annonce doit avoir un abonnement actif et être approuvée.':'For visitors, the listing must have an active subscription and be approved.'}}</p></main>`,styles:[`main{max-width:48rem;margin:4rem auto;padding:1.5rem;font-family:system-ui;color:#173a43}a{display:inline-block;padding:.8rem 1rem;background:#12566a;color:white;border-radius:8px;margin:.5rem .5rem .5rem 0}`]})
export class AssetUnavailableComponent{constructor(public language:LanguageService,private route:ActivatedRoute){}get management(){return this.route.snapshot.queryParamMap.get('reason')==='management';}get lookup(){return this.route.snapshot.queryParamMap.get('reason')==='lookup';}get fr(){return this.language.currentLanguage==='fr';}}
